// ─────────────────────────────────────────────────────────────────────────
// 정규화 — 피드 하나 → POST /ingest 요청 본문 1개
//
// 실행 모드: Run Once for Each Item
// 입력: 「피드 가져오기」의 성공 출력 + 오류 출력이 여기로 합류한다
//
// XML 파싱을 이 노드 안에서 한다. n8n XML 노드를 쓰면 pairedItem 이 끊겨
// $('소스별로 분리').item 이 소스를 못 찾는다. 인덱스로 맞추는 우회는
// 오류 분기가 생기는 순간 어긋나고, 하필 그때 가장 필요하다.
// 본문 HTML 이 전부 CDATA 로 감싸여 있어(실측) 태그 경계는 안전하다.
//
// 원칙: 정규화 실패한 기사도 버리지 않는다. articles 배열에 남겨야
//       collector 가 rejected 로 집계하고, 빈 피드로 오인되지 않는다.
// ─────────────────────────────────────────────────────────────────────────

const src = $('소스별로 분리').item.json;
const nowIso = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');

let cfg = {};
try { cfg = src.config ? JSON.parse(src.config) : {}; } catch (e) { cfg = {}; }
const CONTENT_TAG  = (cfg.rss && cfg.rss.content_tag) || 'description';
const DROP_CLASSES = (cfg.rss && cfg.rss.drop_classes) || [];

// ── XML ─────────────────────────────────────────────────────────────────
function unwrap(s) {
  if (s == null) return null;
  return s.replace(/^\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*$/, '$1');
}

// 속성이 붙은 태그도 값만 뽑는다. <guid isPermaLink="false">…</guid> 처럼.
function tagValue(block, tag) {
  const re = new RegExp(
    `<${tag}(?:\\s[^>]*)?(?:/>|>([\\s\\S]*?)</${tag}>)`, 'i');
  const m = block.match(re);
  if (!m) return null;
  const v = unwrap(m[1]);
  return v == null ? null : (v.trim() || null);
}

function feedItems(xml) {
  if (!xml || !/<rss[\s>]|<feed[\s>]/i.test(xml)) return null;   // 피드가 아니다
  return xml.match(/<item(?:\s[^>]*)?>[\s\S]*?<\/item>/gi)
      || xml.match(/<entry(?:\s[^>]*)?>[\s\S]*?<\/entry>/gi)
      || [];
}

// ── HTML → 텍스트 ────────────────────────────────────────────────────────
// 순서가 중요하다: 클래스 DROP → 태그 DROP(내용까지) → 블록태그를 줄바꿈
//                → 남은 태그 제거 → 엔티티 복원 → 공백 정리
const DROP  = 'script|style|svg|button|noscript|template|iframe|form';
const BLOCK = 'p|div|br|li|tr|h[1-6]|section|article|figcaption|blockquote';

const ENT = {
  '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&apos;': "'",
  '&nbsp;': ' ', '&#39;': "'", '&#160;': ' ', '&hellip;': '…',
  '&ldquo;': '\u201c', '&rdquo;': '\u201d',
  '&lsquo;': '\u2018', '&rsquo;': '\u2019',
  '&mdash;': '\u2014', '&ndash;': '\u2013',
};

// 태그 종류로는 못 거르는 소스별 UI 잔재를 클래스로 지운다.
// Carbon Brief 의 "Article Contents / Expand menu Close" 가 실측 사례 —
// <div class="article-contents__title__text"> 와 <a class="g-button"> 라
// 태그 이름으로는 안 걸린다. 어느 클래스인지는 소스가 알고(config.rss),
// 지우는 방법은 이 코드가 안다.
function dropByClass(s, classes) {
  for (const cls of classes) {
    const re = new RegExp(
      `<(\\w+)\\b[^>]*class="[^"]*${cls}[^"]*"[^>]*>[\\s\\S]*?</\\1>`, 'gi');
    let prev;
    do { prev = s; s = s.replace(re, ' '); } while (s !== prev);   // 중첩 대비
  }
  return s;
}

function stripHtml(html) {
  if (!html) return null;
  let s = String(html);
  if (DROP_CLASSES.length) s = dropByClass(s, DROP_CLASSES);
  s = s.replace(new RegExp(`<(${DROP})\\b[^>]*>[\\s\\S]*?</\\1>`, 'gi'), ' ');
  s = s.replace(new RegExp(`<(${DROP})\\b[^>]*/?>`, 'gi'), ' ');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(new RegExp(`</?(${BLOCK})\\b[^>]*>`, 'gi'), '\n');
  s = s.replace(/<[^>]+>/g, ' ');
  s = s.replace(/&[a-zA-Z]+;|&#\d+;/g, (m) => {
    if (ENT[m]) return ENT[m];
    const n = m.match(/^&#(\d+);$/);
    return n ? String.fromCodePoint(Number(n[1])) : m;
  });
  // CRLF·CR 을 LF 로 먼저 통일한다. 안 하면 '\n\r\n\r\n\n' 이 그대로 남아
  // 빈 줄 정리 정규식을 빠져나가고, 600자 예산을 잡아먹는다 (임팩트온 실측)
  s = s.replace(/\r\n?/g, '\n');
  s = s.replace(/[ \t\u00a0]+/g, ' ');
  s = s.replace(/ *\n *(?:\n *)+/g, '\n\n');
  return s.trim() || null;
}

// 제목은 본문과 처리가 다르다. 태그는 거의 없지만 엔티티는 온다 —
// Carbon Brief 의 'Q&#038;A' 가 실측 사례로, &amp;#038; 가 한 번 풀려
// &#038; 이 된 이중 인코딩이다. 한 번만 복원하면 그대로 남는다.
// 줄바꿈은 제목에 있을 자리가 아니라 공백으로 접는다.
function cleanTitle(raw) {
  if (!raw) return null;
  let s = String(raw).replace(/<[^>]+>/g, ' ');
  for (let i = 0; i < 3; i++) {          // 이중 인코딩 대비. 변화가 없으면 멈춘다
    const before = s;
    s = s.replace(/&[a-zA-Z]+;|&#\d+;/g, (m) => {
      if (ENT[m]) return ENT[m];
      const n = m.match(/^&#(\d+);$/);
      return n ? String.fromCodePoint(Number(n[1])) : m;
    });
    if (s === before) break;
  }
  return s.replace(/\s+/g, ' ').trim() || null;
}

// ── 날짜 ────────────────────────────────────────────────────────────────
// 소스마다 필드도 형식도 다르다 (실측):
//   환경미디어    dc:date  2026-08-25T22:49:26+09:00   오프셋 있음
//   임팩트온      pubDate  2026-08-25 14:20:00         오프셋 없음 · 비표준
//   ESG Today     pubDate  Mon, 24 Aug 2026 ... +0000  RFC822
// 오프셋 없는 문자열을 new Date() 에 그냥 넣으면 로컬 TZ 로 해석된다.
// UTC 컨테이너에서 9시간이 조용히 밀리는 게 정확히 이 경로다.
const HAS_TZ = /(?:Z|[+-]\d{2}:?\d{2}|GMT|UTC)\s*$/i;

function parseOne(s, tzOffset) {
  if (!s) return { at: null, err: null };
  let v = s;
  if (!HAS_TZ.test(v)) {
    if (!tzOffset) return { at: null, err: 'timezone_unknown' };
    v = v.replace(' ', 'T') + tzOffset;
  }
  const d = new Date(v);
  if (isNaN(d.getTime())) return { at: null, err: 'unparsable_date' };
  return { at: d.toISOString().replace(/\.\d{3}Z$/, 'Z'), err: null };
}

function pickDate(block, tzOffset) {
  // dc:date 가 있어도 파싱에 실패하면 pubDate 를 다시 시도한다
  let firstErr = null, sawAny = false;
  for (const tag of ['dc:date', 'pubDate', 'published', 'updated']) {
    const raw = tagValue(block, tag);
    if (!raw) continue;
    sawAny = true;
    const r = parseOne(raw, tzOffset);
    if (r.at) return { at: r.at, err: null };
    if (!firstErr) firstErr = r.err;
  }
  if (!sawAny) return { at: null, err: 'no_date' };
  return { at: null, err: firstErr || 'unparsable_date' };
}

// ── URL · url_key ───────────────────────────────────────────────────────
// 보수적으로 다룬다. 깨진 URL 을 과하게 보정해 다른 주소로 만들면
// 원문과 다른 곳을 가리키는 링크가 저장된다.
const TRACK = /^(utm_.*|fbclid|gclid|igshid|mc_cid|mc_eid|ref)$/i;

function cleanUrl(raw) {
  if (!raw) return null;
  const u = raw.replace(/^["'\s]+|["'\s]+$/g, '');
  return /^https?:\/\/\S+$/i.test(u) ? u : null;
}

function urlKey(u) {
  if (!u) return null;
  let s = u.replace(/^https?:\/\//i, '').replace(/#.*$/, '');
  const qi = s.indexOf('?');
  const path = qi === -1 ? s : s.slice(0, qi);
  const query = qi === -1 ? '' : s.slice(qi + 1);

  const slash = path.indexOf('/');
  const host = (slash === -1 ? path : path.slice(0, slash))
                 .toLowerCase().replace(/^www\./, '');
  const rest = (slash === -1 ? '' : path.slice(slash)).replace(/\/+$/, '');

  // 쿼리를 통째로 털면 안 된다 — 국내 CMS 는 ?idxno=19040 처럼
  // 쿼리에 기사 id 가 있어서, 털면 한 매체의 모든 기사가 같은 키가 된다
  const kept = query
    ? query.split('&').filter((p) => p && !TRACK.test(p.split('=')[0]))
    : [];
  return host + rest + (kept.length ? '?' + kept.sort().join('&') : '');
}

// ── fetch 성공 판정 ─────────────────────────────────────────────────────
// HTTP 성공 AND 피드 파싱 성공. 200 인데 XML 이 깨진 걸 true+articles=[]
// 로 보내면 collector 가 죽은 피드로 집계한다
let fetchOk = true, fetchError = null, blocks = [];

if ($json.error !== undefined) {
  fetchOk = false;
  const e = $json.error;
  fetchError = String((e && (e.message || e.description)) || e).slice(0, 300);
} else {
  blocks = feedItems($json.feed_xml);
  if (blocks === null) {
    fetchOk = false;
    fetchError = 'not_a_feed_or_parse_failed';
    blocks = [];
  }
  // blocks 가 빈 배열이면 구조는 정상인데 기사가 0건 — 이건 진짜 빈 피드다
}

// ── 기사 정규화 ─────────────────────────────────────────────────────────
const articles = blocks.map((b) => {
  const link = cleanUrl(tagValue(b, 'link')) || cleanUrl(tagValue(b, 'guid'));
  const d = pickDate(b, src.tz_offset);
  const body = stripHtml(tagValue(b, CONTENT_TAG));
  const snippet = CONTENT_TAG === 'description'
    ? body
    : stripHtml(tagValue(b, 'description'));

  const a = {
    url: link || '',            // 비어도 남긴다 — collector 가 rejected 로 센다
    url_key: urlKey(link) || '',
    title: cleanTitle(tagValue(b, 'title')) || '',
    guid: tagValue(b, 'guid'),
    snippet: snippet,
    body: body,
    lang: src.lang || null,
  };
  if (d.at) a.published_at = d.at;
  else if (d.err) a.published_at_error = d.err;
  return a;
});

return {
  json: {
    request_id: `${$execution.id}:${src.id}`,
    source_id: src.id,
    fetched_at: nowIso,
    fetch_ok: fetchOk,
    fetch_error: fetchError,
    articles: articles,
  },
};

// due 가 0건이라 수집을 아예 안 했다는 마커.
// 요약 노드가 이걸 보고 processed_sources=0 으로 낸다
return [{ json: { __zero_due: true } }];

// ─────────────────────────────────────────────────────────────────────────
// 수집 요약 — 상위 워크플로(wf_daily)에 완료를 알리는 단일 지점
//
// 실행 모드: Run Once for All Items
//
// 이 노드가 있는 이유는 두 갈래가 한 곳으로 모여야 하기 때문이다.
//   due 0건    → 「소스별로 분리」에서 흐름이 끊겨 뒤가 아예 안 돈다.
//                그래서 앞에서 명시적으로 분기해 이리로 보낸다
//   due 1건 이상 → 소스마다 POST ingest 응답이 하나씩, 최대 4개 아이템
//
// 상위가 "완료"를 읽으려면 항상 정확히 한 건이 나와야 한다.
//
// 실패를 조용히 버리지 않는다. POST ingest 가 onError=continueRegularOutput
// 이라 실패해도 같은 출력으로 흐르는데, 그 아이템은 source_id 가 없고
// error 가 있다. filter 로 걸러내면 실패한 소스가 요약에서 사라지고
// 상위가 "정상 완료"로 읽는다 — empty_streak 을 원인별로 가른 것과 같은 계열이다.
// ─────────────────────────────────────────────────────────────────────────

const items = $input.all().map(i => i.json || {});

// due 0건 분기가 보낸 마커. 그쪽은 수집을 아예 안 했다
const zero = items.find(j => j.__zero_due === true);

const ok   = items.filter(j => j.source_id !== undefined && !j.__zero_due);
const bad  = items.filter(j => j.source_id === undefined && !j.__zero_due);

const sum = (k) => ok.reduce((s, r) => s + (Number(r[k]) || 0), 0);

// due 개수는 GET 응답에서 직접 읽는다. 처리된 수로 역산하면
// 중간에 사라진 소스를 못 본다
let dueSources = 0;
try {
  dueSources = $('GET sources due').first().json.count || 0;
} catch (e) {
  dueSources = zero ? 0 : ok.length + bad.length;
}

const failures = bad.map(j => ({
  error: String((j.error && (j.error.message || j.error.description)) || j.error || 'unknown').slice(0, 200),
}));

return [{
  json: {
    stage: 'collect',
    ok: bad.length === 0,
    due_sources: dueSources,          // 원래 처리해야 했던 소스 수
    processed_sources: ok.length,     // ingest 응답까지 돌아온 수
    failed_sources: bad.length,       // fetch 또는 ingest 실패
    received:   sum('received'),
    inserted:   sum('inserted'),
    active:     sum('active'),
    excluded:   sum('excluded'),
    duplicated: sum('duplicated'),
    rejected:   sum('rejected'),
    failures,
    finished_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
  },
}];
